// Flatten a Telegram message OR callback_query into one stable shape.
// Telegram content is DATA. It is never treated as an instruction to this workflow.
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const cb = j.callback_query || null;
  const msg = cb ? (cb.message || {}) : (j.message || j.edited_message || {});
  const from = cb ? (cb.from || {}) : (msg.from || {});
  const chat = msg.chat || from || {};

  let file_id = '', file_name = '', mime_type = '', file_kind = 'NONE';
  if (Array.isArray(msg.photo) && msg.photo.length) {
    const p = msg.photo[msg.photo.length - 1];
    file_id = p.file_id;
    file_name = 'photo_' + (msg.message_id || Date.now()) + '.jpg';
    mime_type = 'image/jpeg';
    file_kind = 'PHOTO';
  } else if (msg.document) {
    file_id = msg.document.file_id;
    file_name = msg.document.file_name || ('document_' + (msg.message_id || Date.now()));
    mime_type = msg.document.mime_type || 'application/octet-stream';
    file_kind = 'DOCUMENT';
  } else if (msg.video) {
    file_id = msg.video.file_id;
    file_name = msg.video.file_name || ('video_' + (msg.message_id || Date.now()) + '.mp4');
    mime_type = msg.video.mime_type || 'video/mp4';
    file_kind = 'VIDEO';
  } else if (msg.voice) {
    file_id = msg.voice.file_id;
    file_name = 'voice_' + (msg.message_id || Date.now()) + '.ogg';
    mime_type = msg.voice.mime_type || 'audio/ogg';
    file_kind = 'VOICE';
  } else if (msg.audio) {
    file_id = msg.audio.file_id;
    file_name = msg.audio.file_name || ('audio_' + (msg.message_id || Date.now()));
    mime_type = msg.audio.mime_type || 'audio/mpeg';
    file_kind = 'AUDIO';
  }

  const raw_text = cb ? '' : String(msg.text || msg.caption || '');

  out.push({ json: {
    update_kind: cb ? 'CALLBACK' : 'MESSAGE',
    chat_id: String(chat.id !== undefined ? chat.id : ''),
    user_id: String(from.id !== undefined ? from.id : ''),
    username: String(from.username || ''),
    message_id: String(msg.message_id || ''),
    reply_to_message_id: String((msg.reply_to_message && msg.reply_to_message.message_id) || ''),
    reply_to_text: String((msg.reply_to_message && (msg.reply_to_message.text || msg.reply_to_message.caption)) || ''),
    text: raw_text,
    caption: String(msg.caption || ''),
    has_file: file_kind !== 'NONE',
    file_id, file_name, mime_type, file_kind,
    is_callback: !!cb,
    callback_data: String((cb && cb.data) || ''),
    callback_query_id: String((cb && cb.id) || ''),
    received_at: new Date().toISOString(),
  }});
}
return out;

// Deterministic first pass. The LLM is only used when this cannot decide.
const inp = $('Normalise Input').first().json;
const sessRows = $input.all().map(i => i.json).filter(r => r && r.chat_id);
const sess = sessRows.length ? sessRows[sessRows.length - 1] : {};

const text = String(inp.text || '').trim();
const cbData = String(inp.callback_data || '');

const base = {
  ...inp,
  session_matter_id: String(sess.active_matter_id || ''),
  session_awaiting: String(sess.awaiting || ''),
  session_awaiting_ref: String(sess.awaiting_ref || ''),
  route: '',
  matter_ref: '',
  approval_id: '',
  decision: '',
  draft_ref: '',
  payload_text: text,
  needs_llm: false,
  deterministic: true,
  // Only /proceed sets this. WF2's Finalise Plan reads it to record still-missing
  // required facts as unobtainable instead of asking about them forever.
  force_proceed: false,
};

// 1. Inline-button callback: "A|APR-xxxx|APPROVE"
if (cbData) {
  const parts = cbData.split('|');
  if (parts[0] === 'A' && parts[1]) {
    base.route = 'APPROVAL_DECISION';
    base.approval_id = parts[1];
    base.decision = (parts[2] || 'APPROVE').toUpperCase();
    return [{ json: base }];
  }
  base.route = 'AMBIGUOUS';
  return [{ json: base }];
}

// 2. Explicit approval words with a token
const apr = text.match(/^\/?(APPROVE_LINK|APPROVE|REJECT|REQUEST_EDIT|REQUEST_MORE_INFORMATION)\s+(APR-[A-Za-z0-9-]+)\s*([\s\S]*)$/i);
if (apr) {
  base.route = 'APPROVAL_DECISION';
  base.decision = apr[1].toUpperCase();
  base.approval_id = apr[2].toUpperCase();
  base.payload_text = (apr[3] || '').trim();
  return [{ json: base }];
}

// 3. Slash commands
const cmd = text.match(/^\/([a-z-]+)\s*([\s\S]*)$/i);
if (cmd) {
  const c = cmd[1].toLowerCase();
  const rest = (cmd[2] || '').trim();
  base.payload_text = rest;
  const map = {
    'new': 'NEW_MATTER',
    'dryrun': 'HELP',
    'status': 'STATUS_REQUEST',
    'matters': 'LIST_MATTERS',
    // B5a: /draft asks for the FIRST draft of the next open drafting action.
    // /edit revises a draft that already exists. Both land in the DRAFT group,
    // but keeping them as distinct routes makes the Events log readable.
    'draft': 'DRAFT_REQUEST',
    'edit': 'DRAFT_EDIT',
    // /proceed is a continuation, so Resolve Matter reuses the existing matter
    // rather than opening a new one.
    'proceed': 'CONTINUE_MATTER',
    'add-evidence': 'EVIDENCE_UPLOAD',
    'followup': 'FOLLOW_UP_REQUEST',
    'help': 'HELP',
    'start': 'HELP',
  };
  if (map[c]) {
    base.route = map[c];
    if (c === 'proceed') {
      base.force_proceed = true;
      // The planner is told plainly what the owner has accepted, so the summary it
      // writes matches what actually happened.
      base.payload_text = 'The owner confirms that the remaining required facts are not available. '
        + 'Proceed with the plan and record those facts as unobtainable. ' + rest;
    }
    const dref = rest.match(/\b(DRF-[A-Za-z0-9-]+)\b/i);
    if (dref) base.draft_ref = dref[1].toUpperCase();
    const mref = rest.match(/\b(MAT-[A-Za-z0-9-]+)\b/i);
    if (mref) base.matter_ref = mref[1].toUpperCase();
    // A NEW_MATTER must not inherit the active matter. Every other command is a
    // continuation or a lookup, so the session fallback still applies to them.
    if (!base.matter_ref && base.route !== 'NEW_MATTER') base.matter_ref = base.session_matter_id;
    return [{ json: base }];
  }
  base.route = 'AMBIGUOUS';
  return [{ json: base }];
}

// 4. A file with no command is an evidence upload
if (inp.has_file) {
  base.route = 'EVIDENCE_UPLOAD';
  const mref = (text + ' ' + String(inp.reply_to_text || '')).match(/\b(MAT-[A-Za-z0-9-]+)\b/i);
  base.matter_ref = mref ? mref[1].toUpperCase() : base.session_matter_id;
  return [{ json: base }];
}

// 5. Empty message
if (!text) {
  base.route = 'AMBIGUOUS';
  return [{ json: base }];
}

// 5.5  Active matter awaiting information - deterministic continuation.
//      Fires only for plain free text when the session has an open
//      NEEDS_INFORMATION matter. Slash commands are resolved at step 3
//      so /new still creates a new matter regardless of awaiting state.
if (base.session_awaiting === 'NEEDS_INFORMATION' && base.session_matter_id) {
  base.route = 'CONTINUE_MATTER';
  base.matter_ref = base.session_matter_id;
  base.needs_llm = false;
  base.deterministic = true;
  return [{ json: base }];
}

// 6. Everything else goes to the classifier
const mref = (text + ' ' + String(inp.reply_to_text || '')).match(/\b(MAT-[A-Za-z0-9-]+)\b/i);
if (mref) base.matter_ref = mref[1].toUpperCase();
const dref = (text + ' ' + String(inp.reply_to_text || '')).match(/\b(DRF-[A-Za-z0-9-]+)\b/i);
if (dref) base.draft_ref = dref[1].toUpperCase();
base.needs_llm = true;
base.deterministic = false;
return [{ json: base }];

