{
  "type": "object",
  "required": [
    "intent",
    "confidence",
    "matter_ref",
    "clarification_needed",
    "clarification_question",
    "summary"
  ],
  "properties": {
    "intent": {
      "type": "string",
      "enum": [
        "NEW_MATTER",
        "CONTINUE_MATTER",
        "CLARIFICATION_ANSWER",
        "DRAFT_EDIT",
        "STATUS_REQUEST",
        "LIST_MATTERS",
        "FOLLOW_UP_REQUEST",
        "EVIDENCE_NOTE",
        "HELP",
        "AMBIGUOUS"
      ]
    },
    "confidence": {
      "type": "number",
      "description": "0 to 1"
    },
    "matter_ref": {
      "type": "string",
      "description": "MAT-... or empty string"
    },
    "clarification_needed": {
      "type": "boolean"
    },
    "clarification_question": {
      "type": "string"
    },
    "summary": {
      "type": "string",
      "description": "One short sentence, owner facing"
    }
  }
}

