// Fail closed. A malformed classifier answer must never continue silently.
const base = $('Parse Command').first().json;
const allowed = ['NEW_MATTER','CONTINUE_MATTER','CLARIFICATION_ANSWER','DRAFT_EDIT',
  'STATUS_REQUEST','LIST_MATTERS','FOLLOW_UP_REQUEST','EVIDENCE_NOTE','HELP','AMBIGUOUS'];

let raw = $input.first().json;
if (raw && raw.output) raw = raw.output;
if (typeof raw === 'string') {
  try { raw = JSON.parse(raw); } catch (e) { raw = null; }
}

if (!raw || typeof raw !== 'object' || !allowed.includes(raw.intent)) {
  return [{ json: { ...base, route: 'CLASSIFIER_FAILED', json_valid: false,
    failure_reason: 'Classifier returned no usable JSON intent.' } }];
}

// An ABSENT or NON-NUMERIC confidence is not a high confidence.
// Previously: conf = Number(raw.confidence), lowConfidence = !NaN && conf < 0.55,
// confidenceOk = !NaN && conf >= 0.55. Two ways that failed open:
//   1. Omitted confidence made BOTH flags false, so route stayed at the model's
//      chosen intent and a NEW_MATTER reached PLAN with its confidence never
//      measured.
//   2. Number() coerces. confidence: true became 1, and the empty string became 0,
//      so a malformed value was read as a real measurement.
// Confidence must now be an actual finite number. Anything else is unusable, and
// unusable is treated as not meeting the threshold, so it clarifies rather than
// plans. A genuine number is unaffected: >= 0.55 still plans, < 0.55 still
// clarifies, and 0.55 exactly still plans.
const confUsable = typeof raw.confidence === 'number' && Number.isFinite(raw.confidence);
const conf = confUsable ? raw.confidence : NaN;
const confidenceOk = confUsable && conf >= 0.55;
const lowConfidence = !confidenceOk;

// A substantive intent that is merely missing facts is not ambiguous.
// Workflow 2 is the stage that collects missing facts, so let it through to PLAN
// and carry clarification_needed with it.
const substantive = ['NEW_MATTER','CONTINUE_MATTER'];
const clarificationOnlyNeedsFacts = substantive.includes(raw.intent) && confidenceOk;
const clarificationForcesAmbiguous =
  raw.clarification_needed === true && !clarificationOnlyNeedsFacts;

let route = raw.intent;
if (lowConfidence || clarificationForcesAmbiguous) {
  route = 'AMBIGUOUS';
}

// ---- CONTINUITY GUARD ------------------------------------------------------
// Deterministic. It does not rely on the model getting the classification right.
//
// The old expression was:
//   matter_ref: String(raw.matter_ref || base.matter_ref || base.session_matter_id || '')
// so a NEW_MATTER inherited the active session's matter id. On 2026-08-24 an
// employment-contract message arrived while the session still pointed at the
// motor-vehicle matter MAT-20260101-001 from four days earlier, and the id was
// carried forward with it.
//
// WF2's Resolve Matter looks up matter_ref, then session_matter_id, and treats
// the result as a continuation only when route is CONTINUE_MATTER,
// CLARIFICATION_ANSWER, FOLLOW_UP_REQUEST or EVIDENCE_NOTE. The route is
// therefore the real gate. This guard closes the same question on WF1's side, so
// a new matter cannot leave here carrying the previous matter's id, approval, or
// draft reference even if WF2's gate were ever loosened.
//
// Every other route keeps its previous behaviour exactly, including the session
// fallback that free-text STATUS_REQUEST and LIST_MATTERS depend on.
const isNewMatter = route === 'NEW_MATTER';
const matterRef = isNewMatter
  ? ''
  : String(raw.matter_ref || base.matter_ref || base.session_matter_id || '');

return [{ json: {
  ...base,
  route,
  json_valid: true,
  intent_confidence: confUsable ? conf : 0,
  confidence_usable: confUsable,
  clarification_needed: raw.clarification_needed === true,
  clarification_question: String(raw.clarification_question || ''),
  intent_summary: String(raw.summary || ''),
  matter_ref: matterRef,
  approval_id: isNewMatter ? '' : base.approval_id,
  draft_ref: isNewMatter ? '' : base.draft_ref,
}}];

const j = $input.first().json;
const r = String(j.route || 'AMBIGUOUS');
const group = ({
  NEW_MATTER: 'PLAN',
  CONTINUE_MATTER: 'PLAN',
  CLARIFICATION_ANSWER: 'PLAN',
  FOLLOW_UP_REQUEST: 'PLAN',
  EVIDENCE_NOTE: 'PLAN',
  // B5a: an explicit request for a first draft, distinct from revising one.
  DRAFT_REQUEST: 'DRAFT',
  DRAFT_EDIT: 'DRAFT',
  APPROVAL_DECISION: 'APPROVAL',
  EVIDENCE_UPLOAD: 'EVIDENCE',
  STATUS_REQUEST: 'STATUS',
  LIST_MATTERS: 'STATUS',
  HELP: 'HELP',
  AMBIGUOUS: 'CLARIFY',
  CLASSIFIER_FAILED: 'CLARIFY',
})[r] || 'CLARIFY';

return [{ json: { ...j, route: r, route_group: group } }];

const j = $('Resolve Route').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.matter_id);
const wantOne = j.route === 'STATUS_REQUEST' && j.matter_ref;

function line(r) {
  return [
    r.matter_id + '  ' + (r.title || '(untitled)'),
    '  Status: ' + (r.status || 'UNKNOWN'),
    '  Playbook: ' + (r.playbook_id || 'UNASSIGNED'),
    '  Last activity: ' + (r.last_activity_at || r.updated_at || 'unknown'),
  ].join('\n');
}

if (!rows.length) {
  return [{ json: { reply: 'There are no matters on the register yet.\n\nSend a description of a legal task to open one.' } }];
}

if (wantOne) {
  const hit = rows.filter(r => String(r.matter_id).toUpperCase() === String(j.matter_ref).toUpperCase());
  if (!hit.length) {
    return [{ json: { reply: 'I have no matter with the id ' + j.matter_ref + '.\n\nSend /matters to list the open matters.' } }];
  }
  const r = hit[hit.length - 1];
  let missing = [];
  try { missing = JSON.parse(r.missing_facts_json || '[]'); } catch (e) { missing = []; }
  let risks = [];
  try { risks = JSON.parse(r.risk_flags_json || '[]'); } catch (e) { risks = []; }
  const body = [
    line(r),
    '',
    'Missing information: ' + (missing.length ? '\n- ' + missing.join('\n- ') : 'none recorded'),
    'Risk flags: ' + (risks.length ? risks.join(', ') : 'none recorded'),
  ].join('\n');
  return [{ json: { reply: body } }];
}

const open = rows.filter(r => !['CLOSED','REJECTED'].includes(String(r.status || '').toUpperCase()));
const body = 'Open matters (' + open.length + ')\n\n' + open.map(line).join('\n\n');
return [{ json: { reply: body.slice(0, 3800) } }];

const j = $input.first().json;
let q = String(j.clarification_question || '').trim();
if (!q) {
  q = 'I could not tell what you need. Could you say what outcome you want, and who the other party is?';
}
const head = j.route === 'CLASSIFIER_FAILED'
  ? 'I stopped before doing anything, because I could not read that safely.'
  : 'I did not want to guess.';
return [{ json: { reply: head + '\n\n' + q + '\n\nSend /help to see what I can do.' } }];

// Structured return from WF2 Set Return Data node.
// Primary session write already happened inside WF2 (Persist Session node).
// This is the belt-and-suspenders write in case WF2's Persist Session failed.
//
// Fail-closed rules:
//   Never overwrite a valid existing active_matter_id with empty.
//   Do not write if matter_id or chat_id is missing.
//   Do not change another user's session (chat_id guard).
const fromChild = $input.first().json || {};
const route = $('Resolve Route').first().json;

const childMatterId    = String(fromChild.matter_id    || '').trim().toUpperCase();
const childStatus      = String(fromChild.matter_status || '').trim();
const childAwaiting    = String(fromChild.awaiting      || '').trim();
const childAwaitingRef = String(fromChild.awaiting_ref  || '').trim();
const childChatId      = String(fromChild.chat_id       || '').trim();
const ownChatId        = String(route.chat_id           || '').trim();

// Guard: child must belong to this session's chat
const chatMatch = !!childChatId && childChatId === ownChatId;

// Guard: child must have returned a valid matter_id and session_ok
const childSessionOk = fromChild.session_ok === true
                       && !!childMatterId
                       && chatMatch;

// Guard: never overwrite a valid existing matter_id with empty
const existingMatterId = String(route.session_matter_id || '').trim().toUpperCase();
const activeMatterId = childSessionOk
  ? childMatterId
  : (existingMatterId || '');

const awaiting = childSessionOk
  ? childAwaiting
  : String(route.session_awaiting || '').trim();

const awaitingRef = childSessionOk
  ? childAwaitingRef
  : String(route.session_awaiting_ref || '').trim();

return [{ json: {
  chat_id:           ownChatId,
  active_matter_id:  activeMatterId,
  awaiting:          awaiting,
  awaiting_ref:      awaitingRef,
  last_route:        String(route.route || 'NEW_MATTER'),
  _child_session_ok: childSessionOk,
}}];
